Το απόσπασμα της συνεδρίασης είναι το εξής:
[
  {
    "speakerName": "Κώστας Μπακογιάννης",
    "speakerParty": "Αθήνα Ψηλά",
    "utterances": [
      {
        "text": "Επίσης, για την κεραία.",
        "utteranceId": "3iypyu3x"
      },
      {
        "text": "Είναι τεράστιο θέμα.",
        "utteranceId": "hjash4qd"
      },
      {
        "text": "Θα θέλαμε να παρακαλέσουμε, κύριε Δήμαρχε, να προχωρήσει άμεσα ο έλεγχος της πολεοδομίας",
        "utteranceId": "q2cjpakf"
      },
      {
        "text": "και να ενημερώσετε και εμάς εγγράφως για το τι ακριβώς έχει συμβεί.",
        "utteranceId": "om6k1ucg"
      }
    ]
  },
  {
    "speakerName": "Κώστας Ζαχαριάδης",
    "speakerParty": "Ανοιχτή Πόλη",
    "utterances": [
      {
        "text": "Καταρχήν, έλαβα και εγώ αυτό το έγγραφο από την επιτροπή των κατοίκων",
        "utteranceId": "bt8kqzst"
      },
      {
        "text": "Άνω Γαλατσίου και Άνω Κυψέλης.",
        "utteranceId": "8271fcu8"
      },
      {
        "text": "Νομίζω ότι πρέπει να κοιτάξουμε το θέμα που θέτουν με",
        "utteranceId": "m6fopmws"
      },
      {
        "text": "την κεραία και να δούμε τι πρέπει να γίνει, ώστε να τηρηθούν τα όρια και να προστατεύεται η δημόσια υγεία.",
        "utteranceId": "wdf14gey"
      }
    ]
  },
  {
    "speakerName": "Νίκος Σοφιανός",
    "speakerParty": "Λαϊκή Συσπείρωση Αθήνας",
    "utterances": [
      {
        "text": "Το δεύτερο.",
        "utteranceId": "tbtzfqp9"
      },
      {
        "text": "Θεωρούμε ότι υπάρχει ομοφωνία, από ότι κατάλαβα, για τις κινήσεις που πρέπει να γίνουν από πλευράς Δήμου, ώστε να στηριχτεί το αίτημα των κατοίκων όσον αφορά την κεραία στα σύνορα των δύο Δήμων.",
        "utteranceId": "lzavrn3p"
      }
    ]
  },
  {
    "speakerName": "Πέτρος Κωνσταντίνου",
    "speakerParty": "Ανατρεπτική Συμμαχία για την Αθήνα",
    "utterances": [
      {
        "text": "Το τέταρτο για την κεραία.",
        "utteranceId": "jodwe5yd"
      },
      {
        "text": "Επειδή αυτό το Δημοτικό Συμβούλιο σε όλα τα θέματα έχει συναινέσει με τους κατοίκους",
        "utteranceId": "7gcdclej"
      },
      {
        "text": "ή θα το φέρουμε στην επόμενη ημερήσια διάταξη ή απλά νομίζω να στηρίξουμε το αίτημά τους άμεσα.",
        "utteranceId": "mcg9xpqa"
      },
      {
        "text": "Ένα από τα δύο χρειάζεται να γίνει.",
        "utteranceId": "oo7hql1z"
      }
    ]
  }
]

